+//! One executable workflow against real HTTP, Parquet and PostgreSQL boundaries.
+
+use std::{collections::HashMap, path::Path, process::Output};
+
+use axum::{Json, Router, extract::Query, routing::get};
+use serde_json::{Value, json};
+use sqlx::PgPool;
+use tokio::{net::TcpListener, process::Command, task::JoinHandle};
+use uuid::Uuid;
+
+async fn fixture_server() -> (String, JoinHandle<()>) {
+    let app = Router::new()
+        .route("/api/Members/Search", get(|Query(query): Query<HashMap<String, String>>| async move {
+            assert_eq!(query["take"], "20");
+            Json(json!({"items": [{"value": {
+                "id": 1, "nameDisplayAs": "Current Member",
+                "latestParty": {"id": 15, "name": "Party"},
+                "latestHouseMembership": {"house": 1, "membershipFrom": "Somewhere"}
+            }}], "totalResults": 1, "skip": 0, "take": 20}))
+        }))
+        .route("/api/Members/History", get(|| async { Json(json!([{"value": {
+            "id": 1, "houseMembershipHistory": [{"house": 1,
+                "membershipStartDate": "2020-01-01T00:00:00", "membershipEndDate": null}]
+        }}])) }));
+    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
+    let url = format!("http://{}", listener.local_addr().unwrap());
+    let task = tokio::spawn(async move { axum::serve(listener, app).await.unwrap() });
+    (url, task)
+}
+
+async fn command(config: &Path, operation: &str, capture_id: Option<&str>) -> Output {
+    let mut command = Command::new(env!("CARGO_BIN_EXE_exposed"));
+    command.args(["data", operation, "members"]).arg(config);
+    if let Some(id) = capture_id { command.arg(id); }
+    command.kill_on_drop(true).output().await.unwrap()
+}
+
+fn success(output: &Output) -> Value {
+    assert!(output.status.success(), "{}", String::from_utf8_lossy(&output.stderr));
+    serde_json::from_slice(&output.stdout).unwrap()
