/// Production HTTP source for the Commons cohort.
#[derive(Clone)]
pub struct MembersApi { client: Client, base_url: Url }
impl MembersApi {
    /// Build an HTTP client without issuing requests.
    ///
    /// # Errors
    /// Rejects invalid URLs or HTTP client configuration.
    pub fn new(base_url: &str) -> Result<Self, ParliamentApiError> {
        let base_url = Url::parse(base_url).map_err(|_| failure("invalid Members API URL"))?;
        if !matches!(base_url.scheme(), "http" | "https") || base_url.host_str().is_none() || !base_url.username().is_empty() || base_url.password().is_some() {
            return Err(failure("Members API URL must be an HTTP(S) URL without credentials"));
        }
        let client = Client::builder().connect_timeout(Duration::from_secs(10)).timeout(Duration::from_secs(30)).build().map_err(failure)?;
        Ok(Self { client, base_url })
    }

    async fn get(&self, path: &str, params: &[(&str, String)]) -> Result<Vec<u8>, ParliamentApiError> {
        let mut url = self.base_url.join(path).map_err(failure)?;
        url.query_pairs_mut().extend_pairs(params.iter().map(|(key, value)| (*key, value.as_str())));
        // Request context contains source filters/IDs, never connection credentials.
        let context = format!("{path}?{}", url.query().unwrap_or_default());
        for attempt in 0..4 {
            tokio::time::sleep(Duration::from_millis(200)).await;
            let mut delay = Duration::from_secs(1 << attempt);
            let problem = match self.client.get(url.clone()).send().await {
                Ok(response) => {
                    let status = response.status();
                    if status == StatusCode::OK {
                        match response.bytes().await {
                            Ok(bytes) => return Ok(bytes.to_vec()),
                            Err(error) => format!("response transport failure: {error}"),
                        }
                    } else {
                        if status != StatusCode::TOO_MANY_REQUESTS && !status.is_server_error() {
                            return Err(failure(format!("{context}: HTTP {status}")));
                        }
                        if let Some(header) = response.headers().get(reqwest::header::RETRY_AFTER).and_then(|h| h.to_str().ok()) {
                            delay = retry_delay(header).unwrap_or(delay);
                        }
                        format!("HTTP {status}")
                    }
                }
                Err(error) => format!("transport failure: {error}"),
            };
            if attempt == 3 { return Err(failure(format!("{context}: {problem} after four attempts"))); }
            eprintln!("{context}: {problem}; retry {}/4", attempt + 2);
            tokio::time::sleep(delay.min(Duration::from_secs(30))).await;
        }
        unreachable!("four attempts always return success or failure")
    }

    async fn search(&self, filters: Vec<(&str, String)>) -> Result<Vec<MemberProfile>, ParliamentApiError> {
        let mut profiles = Vec::new();
        let mut offset = 0;
        loop {
            let mut params = filters.clone();
            params.extend([("skip", offset.to_string()), ("take", "20".to_owned())]);
            let bytes = self.get("/api/Members/Search", &params).await?;
            let context = format!("/api/Members/Search {params:?}");
            let page: SearchPage = decode(&bytes, &context)?;
            if page.skip != offset { return Err(failure(format!("{context}: response skip {} does not match request {offset}", page.skip))); }
            if page.items.is_empty() && offset < page.total_results { return Err(failure(format!("{context}: premature empty page before total {}", page.total_results))); }
            offset = offset.checked_add(page.items.len()).ok_or_else(|| failure("search pagination overflow"))?;
            for value in page.items {
