#[derive(Parser)]
struct Cli { #[command(subcommand)] command: Commands }
#[derive(Subcommand)]
enum Commands { Server { config: PathBuf }, Data(DataArgs) }
#[derive(Args)]
struct DataArgs { #[command(subcommand)] command: DataCommands }
#[derive(Subcommand)]
enum DataCommands {
    Fetch { #[command(subcommand)] target: FetchTarget },
    Load { #[command(subcommand)] target: LoadTarget },
    Clean { config: PathBuf },
    Resolve { config: PathBuf },
}
#[derive(Subcommand)]
enum FetchTarget { Members { config: PathBuf } }
#[derive(Subcommand)]
enum LoadTarget { Members { config: PathBuf, capture_id: CaptureId } }

#[tokio::main]
async fn main() -> ExitCode {
    let args = Cli::parse();
    // Dropping the operation on Ctrl-C drops an in-flight transaction. Capture
    // publication is synchronous once source acquisition has finished.
    tokio::select! {
        result = run(args) => match result {
            Ok(()) => ExitCode::SUCCESS,
            Err(error) => { eprintln!("{error:#}"); ExitCode::from(1) }
        },
        _ = tokio::signal::ctrl_c() => { eprintln!("Interrupted"); ExitCode::from(130) }
    }
}
async fn run(args: Cli) -> anyhow::Result<()> {
    let outcome: EntityIngestionOutcome = match args.command {
        Commands::Server { config } => { return serve_exposed(&Config::try_from(&config)?).await; }
        Commands::Data(DataArgs { command: DataCommands::Fetch { target: FetchTarget::Members { config } } }) => {
            let started_at = Utc::now();
            let observation_date = started_at.with_timezone(&chrono_tz::Europe::London).date_naive();
            let config: MemberFetchConfig = read_data_config(&config).context("invalid member Fetch configuration")?;
            ensure!(!config.data_root.as_os_str().is_empty(), "data_root must not be empty");
            let source = MembersApi::new(&config.members_api_url)?;
            let storage = ExposedDataPipeline::new(config.data_root);
