        }
        Commands::Data(DataArgs { command: DataCommands::Load { target: LoadTarget::Members { config, capture_id } } }) => {
            let config: MemberLoadConfig = read_data_config(&config).context("invalid member Load configuration")?;
            ensure!(!config.data_root.as_os_str().is_empty(), "data_root must not be empty");
            let storage = ExposedDataPipeline::new(config.data_root);
            let database = MemberDatabase::new(&config.connection_string)?;
            LoadService::new(storage, database).run_ingestion(&EntityIngestionRequest::new_members_request(MemberIngestionStage::Load { capture_id })).await?
        }
        Commands::Data(_) => anyhow::bail!("declaration cleaning and resolution are not implemented"),
    };
    let mut summary = serde_json::to_value(outcome)?;
    summary["status"] = "succeeded".into();
    println!("{}", serde_json::to_string(&summary)?);
    Ok(())
}
