#[derive(Clone, Copy, PartialEq, Eq)]
enum Fixture { Original, Corrected, SourceFailure }

struct FixtureServer { url: String, task: JoinHandle<()> }
impl Drop for FixtureServer { fn drop(&mut self) { self.task.abort(); } }
impl FixtureServer {
    async fn start(mode: Fixture) -> Self {
        let app = Router::new().route("/api/Members/Search", get(search)).route("/api/Members/History", get(histories)).with_state(mode);
        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
