//! Validated members used by both search and member ingestion.
use thiserror::Error;

/// Member of Parliament with the required profile and current Commons status.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ParliamentMember {
    name: String,
    parliament_member_id: i32,
    party_id: i32,
    party_name: String,
    latest_house: i16,
    latest_membership_from: String,
    is_current_commons: bool,
}

impl ParliamentMember {
    /// Create a member whose profile and current status are consistent.
    ///
    /// # Errors
    /// Rejects invalid identities, a blank name, an unknown House, or current
    /// Commons status with a latest Lords profile.
    pub fn new(name: String, parliament_member_id: i32, party_id: i32, party_name: String, latest_house: i16, latest_membership_from: String, is_current_commons: bool) -> Result<Self, ParliamentMemberError> {
        if parliament_member_id <= 0 { return Err(ParliamentMemberError::InvalidField { member_id: parliament_member_id, field: "parliament_member_id" }); }
        if name.trim().is_empty() { return Err(ParliamentMemberError::InvalidField { member_id: parliament_member_id, field: "name" }); }
        if party_id <= 0 { return Err(ParliamentMemberError::InvalidField { member_id: parliament_member_id, field: "party_id" }); }
        if !matches!(latest_house, 1 | 2) || (is_current_commons && latest_house != 1) {
            return Err(ParliamentMemberError::InvalidField { member_id: parliament_member_id, field: "latest_house" });
        }
        Ok(Self { name, parliament_member_id, party_id, party_name, latest_house, latest_membership_from, is_current_commons })
    }
    /// Member's source display name.
    #[must_use]
    pub fn name(&self) -> &str { &self.name }
    /// Parliament's numeric member identity.
    #[must_use]
    pub const fn parliament_member_id(&self) -> i32 { self.parliament_member_id }
    /// Required latest party identity.
    #[must_use]
    pub const fn party_id(&self) -> i32 { self.party_id }
    /// Required latest party name.
    #[must_use]
    pub fn party_name(&self) -> &str { &self.party_name }
    /// Latest House from the member profile.
    #[must_use]
    pub const fn latest_house(&self) -> i16 { self.latest_house }
    /// Required latest membership location.
    #[must_use]
    pub fn latest_membership_from(&self) -> &str { &self.latest_membership_from }
    /// Status observed in the current Commons search.
    #[must_use]
    pub const fn is_current_commons(&self) -> bool { self.is_current_commons }
}

/// A member profile cannot be represented by a valid domain member.
#[derive(Error, Debug)]
pub enum ParliamentMemberError {
    /// A required value is invalid or inconsistent with current membership.
    #[error("member {member_id}: invalid {field}")]
    InvalidField { /// Parliament's numeric member identity.
        member_id: i32, /// Invalid source field.
        field: &'static str },
}
